/**
 * Longest haul — answers “what was the longest I drove without getting out?”
 *
 * The index ships `longest_drive_miles` and `longest_drive_to` (the longest
 * run of driving legs between stops, summed at export). A photograph does
 * not end the run. A dwell, a walk, or a ferry does. Nothing here fetches
 * geometry or moves the camera.
 */
import type { Trip } from "../types";
import { formatModeMiles, roadPlace } from "./on-foot";
import { placeFromLabel } from "./travel-caption";

/** A Supercharger hop under this is ordinary. The line names a real sitting. */
export const MIN_HAUL_MILES = 80;

export interface Haul {
  miles: number;
  /** Town or landmark the sitting arrived at. Empty when the leg had no place. */
  to: string;
}

export interface HaulPick {
  id: string;
  miles: number;
  /** "Longest haul · 186 mi · Frisco → Colorado" */
  sheetLabel: string;
}

interface DriveSegment {
  type?: string;
  profile?: string;
  leg_miles?: number;
  to_label?: string;
}

/** Town or landmark. Drops a photo prefix, a house number, and a trailing state. */
export function haulPlace(label: unknown): string {
  return placeFromLabel(label).replace(/,\s*[A-Z]{2}$/, "").trim();
}

function closeRun(
  best: Haul,
  runMiles: number,
  runTo: string,
): Haul {
  if (runMiles > 0 && runMiles >= best.miles) {
    return { miles: runMiles, to: runTo };
  }
  return best;
}

/** Longest driving sitting in a playback timeline. Zero when there is none. */
export function haulFromSegments(segments: unknown): Haul {
  let best: Haul = { miles: 0, to: "" };
  let runMiles = 0;
  let runTo = "";
  const list = Array.isArray(segments) ? segments : [];
  const close = () => {
    best = closeRun(best, runMiles, runTo);
    runMiles = 0;
    runTo = "";
  };
  for (const raw of list) {
    if (!raw || typeof raw !== "object") {
      close();
      continue;
    }
    const seg = raw as DriveSegment;
    if (seg.type === "memory") continue;
    if (seg.type === "travel" && String(seg.profile || "driving") === "driving") {
      const miles = Number(seg.leg_miles) || 0;
      if (miles > 0) runMiles += miles;
      const place = haulPlace(seg.to_label);
      if (place) runTo = place;
      continue;
    }
    close();
  }
  close();
  return best;
}

/**
 * Prefer the export numbers so the label cannot drift when a chunk loads.
 * A missing field (an index from before this export) falls back to segments.
 */
export function haulOf(trip: Pick<Trip, "longest_drive_miles" | "longest_drive_to" | "playback"> | null | undefined): Haul | null {
  if (!trip) return null;
  let miles = 0;
  let to = "";
  if (trip.longest_drive_miles != null) {
    miles = Number(trip.longest_drive_miles) || 0;
    to = haulPlace(trip.longest_drive_to);
  } else {
    const playback = trip.playback as { segments?: unknown } | undefined;
    const fromChunk = haulFromSegments(playback?.segments);
    miles = fromChunk.miles;
    to = fromChunk.to;
  }
  if (miles < MIN_HAUL_MILES) return null;
  return { miles, to };
}

/** "Longest haul · 186 mi to Pendleton" — empty under the floor. */
export function haulLabel(trip: Pick<Trip, "longest_drive_miles" | "longest_drive_to" | "playback"> | null | undefined): string {
  const haul = haulOf(trip);
  if (!haul) return "";
  const miles = formatModeMiles(haul.miles);
  return haul.to ? `Longest haul · ${miles} mi to ${haul.to}` : `Longest haul · ${miles} mi`;
}

function beats(candidate: Trip, miles: number, best: Trip, bestMiles: number): boolean {
  if (miles > bestMiles + 1e-9) return true;
  if (Math.abs(miles - bestMiles) > 1e-9) return false;
  const tripMiles = Number(candidate.miles) || 0;
  const bestTripMiles = Number(best.miles) || 0;
  if (tripMiles !== bestTripMiles) return tripMiles > bestTripMiles;
  return String(candidate.start || "") > String(best.start || "");
}

/**
 * The road with the longest sitting. Ties: more total miles, then the later
 * start. Short drives count.
 */
export function mostHaul(trips: readonly Trip[]): HaulPick | null {
  let best: Trip | null = null;
  let bestMiles = 0;
  for (const trip of trips) {
    const haul = haulOf(trip);
    if (!haul) continue;
    if (!best || beats(trip, haul.miles, best, bestMiles)) {
      best = trip;
      bestMiles = haul.miles;
    }
  }
  if (!best) return null;
  return {
    id: best.id,
    miles: bestMiles,
    sheetLabel: `Longest haul · ${formatModeMiles(bestMiles)} mi · ${roadPlace(best)}`,
  };
}
