/**
 * Clock rate policy.
 *
 * timeline-ms per wall-ms = uiSpeed × PLAYBACK_SPEED_REF × pace × governor
 *
 * - `PLAYBACK_SPEED_REF` makes UI 1× a pace you can follow. 0.28 outran satellite
 *   tiles; 0.18 was still a blur on a mountain highway. 0.09 is the old 0.5×,
 *   so 0.25× and 0.5× are there when you want to read the road.
 * - `pace` is the story ease: the last 10 % of a leg that ends at a photo slows
 *   to 0.6× so the photograph can arrive. A memory hold runs at
 *   `MEMORY_HOLD_PACE` so the still lasts about as long as it did before the
 *   drive was slowed. The Highlights reel multiplies plain travel by 2.8×.
 *   Intro, overnight dwells and the title card are never multiplied.
 * - `governor` (see buffer-governor) eases the clock when a basemap that
 *   reports readiness is starved. Photorealistic 3D reports no signal and
 *   does not slow the clock on frame time (that play/stall cadence was the
 *   heavy mesh, not missing tiles).
 */

import type { PlaybackPosition } from "./types";

/** UI 1×. Equal to the previous 0.5× (old ref 0.18), so the road can be read. */
export const PLAYBACK_SPEED_REF = 0.09;
/**
 * Memory holds stay near the old wall-clock length (~12 s) while travel runs
 * at the slower ref. 2 × 0.09 = the previous 1× rate.
 */
export const MEMORY_HOLD_PACE = 2;
export const SPEED_MIN = 0.25;
export const SPEED_MAX = 4;
export const SPEED_STEP = 0.25;
/** Presets surfaced in the Watch transport; the slider stays continuous. */
export const SPEED_PRESETS: readonly number[] = [0.5, 1, 1.5, 2, 3];
export const HIGHLIGHT_TRAVEL_MULT = 2.8;
export const APPROACH_EASE_START = 0.9;
export const APPROACH_EASE_FLOOR = 0.6;

export function clampSpeed(v: number): number {
  const n = Number(v);
  if (!Number.isFinite(n)) return 1;
  return Math.max(SPEED_MIN, Math.min(SPEED_MAX, Math.round(n * 100) / 100));
}

/**
 * A saved UI speed, or null when this browser has no choice yet.
 * A missing key must stay null: `Number(null)` is 0, and clamping 0 up to
 * the floor would lock every first visit at 0.25×.
 */
export function parseSavedSpeed(raw: string | null | undefined): number | null {
  if (raw == null || raw === "") return null;
  const n = Number(raw);
  if (!Number.isFinite(n)) return null;
  return clampSpeed(n);
}

/** Next preset in `dir` (wraps); a value between presets moves to the neighbour in that direction. */
export function nextPreset(current: number, dir: 1 | -1): number {
  const presets = SPEED_PRESETS;
  if (dir > 0) {
    const up = presets.find((p) => p > current + 1e-9);
    return up ?? presets[0];
  }
  for (let i = presets.length - 1; i >= 0; i--) if (presets[i] < current - 1e-9) return presets[i];
  return presets[presets.length - 1];
}

export function isPreset(v: number): boolean {
  return SPEED_PRESETS.some((p) => Math.abs(p - v) < 1e-9);
}

/** Story ease for the final approach to a photo: 1 → 0.6 over the last 10 % of the leg. */
export function approachEase(frac: number, photoNext: boolean): number {
  if (!photoNext || frac <= APPROACH_EASE_START) return 1;
  const t = Math.min(1, ((frac - APPROACH_EASE_START) / (1 - APPROACH_EASE_START)) * 1.4);
  return 1 - (1 - APPROACH_EASE_FLOOR) * t;
}

export interface PaceOptions {
  highlightReel?: boolean;
}

function isPhotoHold(pos: PlaybackPosition): boolean {
  if (pos.phase === "memory") return true;
  return pos.phase === "dwell" && !!pos.segment.raw.is_photo;
}

/** Multiplier on top of the fixed clock for the current position. */
export function paceMultiplier(pos: PlaybackPosition | null | undefined, opts: PaceOptions = {}): number {
  if (!pos) return 1;
  // A photograph should linger, not inherit the slower cruise or the reel.
  if (isPhotoHold(pos)) return MEMORY_HOLD_PACE;
  if (pos.phase !== "travel") return 1;
  let pace = approachEase(pos.frac, pos.segment.photoNext);
  if (opts.highlightReel && pace >= 0.98) pace *= HIGHLIGHT_TRAVEL_MULT;
  return pace;
}

/** timeline-ms advanced per wall-ms. */
export function timelineRate(uiSpeed: number, pace: number, governor: number): number {
  return clampSpeed(uiSpeed) * PLAYBACK_SPEED_REF * pace * Math.max(0, governor);
}

/** Compact control label (buttons stay short). */
export function formatSpeedLabel(v: number): string {
  const n = Math.round(Number(v) * 100) / 100;
  if (!Number.isFinite(n)) return "1×";
  const text = Number.isInteger(n) ? String(n) : n.toFixed(2).replace(/\.?0+$/, "");
  return `${text}×`;
}

/** Spoken/aria label so 1× reads as cruise pace, not a mystery multiplier. */
export function formatSpeedAriaLabel(v: number): string {
  const n = Math.round(Number(v) * 100) / 100;
  if (!Number.isFinite(n)) return "Cruise pace, 1×";
  if (Math.abs(n - 0.5) < 1e-9) return "Slow pace, 0.5×";
  if (Math.abs(n - 1) < 1e-9) return "Cruise pace, 1×";
  if (Math.abs(n - 1.5) < 1e-9) return "Brisk pace, 1.5×";
  if (Math.abs(n - 2) < 1e-9) return "Fast pace, 2×";
  if (Math.abs(n - 3) < 1e-9) return "Very fast, 3×";
  return `Playback speed ${formatSpeedLabel(n)}`;
}
