/**
 * Departure clock — answers “when did this road leave, and when did it come home?”
 *
 * The first and last stops on the index are the bookends (the same clocks the
 * Start pin uses). Longitude picks the wall-clock zone, matching `tripTzFromLng`
 * in the Watch clock. Nothing here fetches geometry or moves the camera.
 * Place names, street numbers, crew, kWh, VIN, and invoices are never read.
 */
import type { Trip, TripStop } from "../types";
import { roadPlace } from "./on-foot";

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/** A return closer than this is the same moment, not a homecoming. */
export const MIN_RETURN_MS = 10 * 60 * 1000;

/** Under two hours the road never really left. It does not win the sheet. */
export const MIN_AWAY_MS = 2 * 60 * 60 * 1000;

/** Under a day and a half, name hours. Past that, name calendar days. */
const HOURS_BEFORE_DAYS = 36;

export interface LocalClock {
  ms: number;
  /** "7:02 AM" */
  time: string;
  /** "Sep" */
  month: string;
  day: number;
  /** YYYY-MM-DD in the zone at that longitude. */
  key: string;
}

export interface AwayPick {
  id: string;
  spanMs: number;
  /** "Away the longest · 21 days · Bellevue → Redondo Beach" */
  sheetLabel: string;
}

/**
 * Wall-clock zone from longitude. Same bands as the Watch clock:
 * 0° is unused; −112.5° is the Pacific / Mountain cut this diary uses.
 */
export function tripTzFromLng(lng: number | null | undefined): string {
  if (lng == null || !Number.isFinite(lng)) return "America/Chicago";
  if (lng <= -112.5) return "America/Los_Angeles";
  if (lng <= -100) return "America/Denver";
  if (lng <= -85) return "America/Chicago";
  return "America/New_York";
}

/** A clock instant. A bare calendar day is not a time of day. */
export function parseRoadInstant(raw: unknown): Date | null {
  if (raw == null) return null;
  let text = String(raw).trim();
  if (!text || /^\d{4}-\d{2}-\d{2}$/.test(text)) return null;
  if (/^\d{4}-\d{2}-\d{2} /.test(text)) text = `${text.slice(0, 10)}T${text.slice(11)}`;
  const ms = Date.parse(text);
  if (!Number.isFinite(ms)) return null;
  return new Date(ms);
}

function part(parts: Intl.DateTimeFormatPart[], type: Intl.DateTimeFormatPartTypes): string {
  return parts.find((p) => p.type === type)?.value || "";
}

export function localClock(dt: Date, lng: number | undefined): LocalClock | null {
  if (!(dt instanceof Date) || Number.isNaN(dt.getTime())) return null;
  let parts: Intl.DateTimeFormatPart[];
  try {
    parts = new Intl.DateTimeFormat("en-US", {
      timeZone: tripTzFromLng(lng),
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hourCycle: "h23",
    }).formatToParts(dt);
  } catch {
    return null;
  }
  const year = part(parts, "year");
  const monthNum = Number(part(parts, "month"));
  const day = Number(part(parts, "day"));
  let hour24 = Number(part(parts, "hour"));
  const minute = part(parts, "minute");
  if (!year || !monthNum || !day || !Number.isFinite(hour24) || !minute) return null;
  if (hour24 === 24) hour24 = 0;
  const mer = hour24 >= 12 ? "PM" : "AM";
  let h12 = hour24 % 12;
  if (h12 === 0) h12 = 12;
  const month = MONTHS[monthNum - 1] || "";
  if (!month) return null;
  return {
    ms: dt.getTime(),
    time: `${h12}:${minute} ${mer}`,
    month,
    day,
    key: `${year}-${String(monthNum).padStart(2, "0")}-${String(day).padStart(2, "0")}`,
  };
}

function stopClock(stop: TripStop | undefined): LocalClock | null {
  if (!stop) return null;
  const dt = parseRoadInstant(stop.datetime);
  if (!dt) return null;
  return localClock(dt, stop.lng);
}

function firstClock(stops: TripStop[]): { stop: TripStop; clock: LocalClock } | null {
  for (const stop of stops) {
    const clock = stopClock(stop);
    if (clock) return { stop, clock };
  }
  return null;
}

function lastClock(stops: TripStop[]): { stop: TripStop; clock: LocalClock } | null {
  for (let i = stops.length - 1; i >= 0; i--) {
    const clock = stopClock(stops[i]);
    if (clock) return { stop: stops[i], clock };
  }
  return null;
}

function cameHome(trip: Trip, last: TripStop | undefined): boolean {
  if (last?.is_home_anchor) return true;
  const origin = String(trip.origin_label || "").trim().toLowerCase();
  const dest = String(trip.story_dest || trip.dest_label || "").trim().toLowerCase();
  if (origin && dest && origin === dest) return true;
  return /\(round trip\)/i.test(String(trip.name || ""));
}

interface Bookends {
  leave: LocalClock;
  back: LocalClock | null;
  home: boolean;
}

function bookends(trip: Trip | null | undefined): Bookends | null {
  const stops = Array.isArray(trip?.stops) ? trip.stops : [];
  const leave = firstClock(stops);
  if (!leave || !trip) return null;
  const ret = lastClock(stops);
  let back: LocalClock | null = null;
  let homeStop: TripStop | undefined;
  if (ret && ret.clock.ms >= leave.clock.ms + MIN_RETURN_MS && ret !== leave) {
    back = ret.clock;
    homeStop = ret.stop;
  }
  return { leave: leave.clock, back, home: cameHome(trip, homeStop || leave.stop) };
}

/** Inclusive calendar days between two local dates (YYYY-MM-DD). */
export function inclusiveDays(startKey: string, endKey: string): number {
  const a = Date.parse(`${startKey}T00:00:00Z`);
  const b = Date.parse(`${endKey}T00:00:00Z`);
  if (!Number.isFinite(a) || !Number.isFinite(b)) return 1;
  return Math.max(1, Math.round((b - a) / 86400000) + 1);
}

/** "21 days" or "18 hours" — the time between the two bookends. */
export function awaySpanPhrase(leave: LocalClock, back: LocalClock): string {
  const hours = (back.ms - leave.ms) / 3_600_000;
  if (hours < HOURS_BEFORE_DAYS) {
    const h = Math.max(1, Math.round(hours));
    return `${h} hour${h === 1 ? "" : "s"}`;
  }
  const days = inclusiveDays(leave.key, back.key);
  return `${days} day${days === 1 ? "" : "s"}`;
}

/**
 * "Left Sep 25 at 7:02 AM · home Sep 29 at 8:41 AM".
 * Same local day drops the dates. A one-way ending says arrived.
 * Empty when the index has no clock.
 */
export function departLabel(trip: Trip | null | undefined): string {
  const ends = bookends(trip);
  if (!ends) return "";
  const { leave, back, home } = ends;
  if (!back) return `Left at ${leave.time}`;
  const verb = home ? "home" : "arrived";
  if (leave.key === back.key) return `Left at ${leave.time} · ${verb} at ${back.time}`;
  return `Left ${leave.month} ${leave.day} at ${leave.time} · ${verb} ${back.month} ${back.day} at ${back.time}`;
}

function beats(span: number, trip: Trip, bestSpan: number, best: Trip): boolean {
  if (span > bestSpan + 1000) return true;
  if (Math.abs(span - bestSpan) > 1000) return false;
  const miles = Number(trip.miles) || 0;
  const bestMiles = Number(best.miles) || 0;
  if (miles !== bestMiles) return miles > bestMiles;
  return String(trip.start || "") > String(best.start || "");
}

/**
 * The road whose bookends sit farthest apart. Ties: more miles, then the
 * later start. A gap under two hours does not count.
 */
export function longestAway(trips: readonly Trip[]): AwayPick | null {
  let best: Trip | null = null;
  let bestSpan = 0;
  let bestEnds: Bookends | null = null;
  for (const trip of trips) {
    const ends = bookends(trip);
    if (!ends?.back) continue;
    const span = ends.back.ms - ends.leave.ms;
    if (span < MIN_AWAY_MS) continue;
    if (!best || !bestEnds || beats(span, trip, bestSpan, best)) {
      best = trip;
      bestSpan = span;
      bestEnds = ends;
    }
  }
  if (!best || !bestEnds?.back) return null;
  const spanLabel = awaySpanPhrase(bestEnds.leave, bestEnds.back);
  return {
    id: best.id,
    spanMs: bestSpan,
    sheetLabel: `Away the longest · ${spanLabel} · ${roadPlace(best)}`,
  };
}
