/**
 * Watch story line — answers “how many miles are left on this leg, and which way?”
 *
 * The clock under the brand is film time. This line is the road: miles still
 * to the next place, the compass of the mile you are on, and whether that
 * stretch is a drive, a walk, or a ferry. Nothing here fetches geometry or
 * moves the camera.
 */
import { formatModeMiles } from "./on-foot";

/** Inside the last mile the number is noise. Say you are arriving. */
export const APPROACH_MILES = 1;

/** Eight points. 0° is north and 90° is east — the same course the chase uses. */
const COMPASS = [
  "north",
  "northeast",
  "east",
  "southeast",
  "south",
  "southwest",
  "west",
  "northwest",
] as const;

const SECTOR_DEG = 45;
/** Keep the current point until the course is this far past its boundary. */
const HOLD_PAST_DEG = 12;

export interface TravelLeg {
  frac?: number;
  profile?: string;
  label?: string;
  legMiles?: number;
  /** Course in degrees. 0 is north, 90 is east. Omit when the course is unknown. */
  bearing?: number;
  /** Previous compass word, so a sector boundary does not flicker. */
  compassHold?: string;
  /** Already-resolved compass word. Wins over `bearing`. */
  heading?: string;
}

function clamp01(value: unknown): number {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(1, n));
}

function norm360(deg: number): number {
  return ((deg % 360) + 360) % 360;
}

function angleDelta(a: number, b: number): number {
  const d = Math.abs(norm360(a) - norm360(b));
  return d > 180 ? 360 - d : d;
}

/**
 * Compass word for a course. `hold` stays until the course is 12° past that
 * sector, so a hairpin sitting on a boundary does not flip the line.
 * An unknown course returns "".
 */
export function compassWord(bearing: unknown, hold?: string): string {
  const b = Number(bearing);
  if (!Number.isFinite(b)) return "";
  const next = COMPASS[Math.round(norm360(b) / SECTOR_DEG) % COMPASS.length];
  const sticky = COMPASS.find((point) => point === hold);
  if (!sticky || sticky === next) return next;
  const center = COMPASS.indexOf(sticky) * SECTOR_DEG;
  if (angleDelta(b, center) < SECTOR_DEG / 2 + HOLD_PAST_DEG) return sticky;
  return next;
}

function headingOf(leg: TravelLeg): string {
  const given = String(leg.heading ?? "").trim().toLowerCase();
  if (given && (COMPASS as readonly string[]).includes(given)) return given;
  return compassWord(leg.bearing, leg.compassHold);
}

/** Town or landmark. Drops a photo prefix and a leading house number. */
export function placeFromLabel(label: unknown): string {
  let text = String(label ?? "")
    .replace(/^photo\s*[·•|-]\s*/i, "")
    .trim();
  if (!text || /^photo$/i.test(text)) return "";
  text = text.replace(/^\d+\s+/, "").trim();
  return text;
}

function modeWord(profile: string): "driving" | "walking" | "ferry" {
  if (profile === "walking" || profile === "ferry") return profile;
  return "driving";
}

function unnamed(mode: "driving" | "walking" | "ferry", heading: string): string {
  if (heading) {
    if (mode === "walking") return `On foot ${heading}`;
    if (mode === "ferry") return `By ferry ${heading}`;
    return `Headed ${heading}`;
  }
  if (mode === "walking") return "On foot";
  if (mode === "ferry") return "Ferry";
  return "On the road";
}

function namedWithoutMiles(mode: "driving" | "walking" | "ferry", dest: string, heading: string): string {
  if (heading) {
    if (mode === "walking") return `On foot ${heading} · ${dest}`;
    if (mode === "ferry") return `By ferry ${heading} · ${dest}`;
    return `Headed ${heading} · ${dest}`;
  }
  if (mode === "walking") return `On foot · ${dest}`;
  if (mode === "ferry") return `By ferry · ${dest}`;
  return `En route · ${dest}`;
}

function namedWithMiles(
  mode: "driving" | "walking" | "ferry",
  miles: string,
  dest: string,
  heading: string,
): string {
  const dir = heading ? ` ${heading}` : "";
  if (mode === "walking") return `${miles} mi on foot${dir} to ${dest}`;
  if (mode === "ferry") return `${miles} mi by ferry${dir} to ${dest}`;
  return `${miles} mi${dir} to ${dest}`;
}

/**
 * Caption for a moving leg. A leg shorter than a mile never grows a distance
 * (a driveway). The last mile of a longer leg reads Approaching.
 */
export function travelCaption(leg: TravelLeg | null | undefined): string {
  if (!leg) return "On the road";
  const mode = modeWord(String(leg.profile || "driving"));
  const dest = placeFromLabel(leg.label);
  const heading = headingOf(leg);
  const frac = clamp01(leg.frac);
  const total = Number(leg.legMiles);
  const known = Number.isFinite(total) && total > 0;
  const remaining = known ? total * (1 - frac) : null;

  if (!known || remaining == null) {
    return dest ? namedWithoutMiles(mode, dest, heading) : unnamed(mode, heading);
  }
  if (total < APPROACH_MILES) {
    if (!dest) return unnamed(mode, heading);
    if (frac >= 0.6) return `Approaching ${dest}`;
    return namedWithoutMiles(mode, dest, heading);
  }
  if (remaining < APPROACH_MILES) {
    return dest ? `Approaching ${dest}` : unnamed(mode, heading);
  }
  const miles = formatModeMiles(remaining);
  return dest ? namedWithMiles(mode, miles, dest, heading) : unnamed(mode, heading);
}
